param([string]$PastaDestino = [Environment]::GetFolderPath('Desktop'), [switch]$NaoPublicar)
$ErrorActionPreference = 'Stop'
if (-not (Test-Path -LiteralPath $PastaDestino -PathType Container)) { throw 'Pasta de destino inexistente.' }
if (-not $NaoPublicar) {
    foreach ($command in @('node','npm.cmd','npx.cmd')) {
        if (-not (Get-Command $command -ErrorAction SilentlyContinue)) { throw ('Instale Node.js 22+ e reabra o PowerShell. Comando ausente: ' + $command) }
    }
    $nodeVersion = (& node --version | Out-String).Trim()
    if ($LASTEXITCODE -ne 0 -or $nodeVersion -notmatch '^v(\d+)\.' -or [int]$matches[1] -lt 22) { throw 'Precisa de Node.js 22 ou superior.' }
}
$site = Join-Path $PastaDestino ('Central-IPTV-listas-alternativas-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '-' + [guid]::NewGuid().ToString('N').Substring(0,8))
New-Item -ItemType Directory -Path $site | Out-Null
$archive = Join-Path $site 'central.zip'
